"""Authored research cards, never native runtime input or an activation profile."""
CARDS = []

def c(n,title,terms,slots,nodes,edges,en,ko,confusions,limit,sources='',mode='still',priority='P1',review=''):
    owners=[{'id':x.split('=',1)[0],'visible_component_en':x.split('=',1)[1]} for x in nodes.split(';') if x]
    relations=[dict(zip(('subject','predicate','object'),x.split('>'))) for x in edges.split(';') if x]
    CARDS.append(dict(id=f'G{n:02d}',title_ko=title,seed_terms=terms.split('|'),evidence_mode=mode,
        proposed_current_slots=slots.split('|') if slots else [],owners=owners,relations=relations,
        phrase_en=en,phrase_ko=ko,confusion_boundaries=confusions.split('|'),claim_limit_ko=limit,
        source_ids=sources.split('|') if sources else [],priority=priority,
        source_support='Sources support only their stated object, historical context or literary example; the proposed geometry and scene are independently authored, not a source quote.',
        review_before_adoption=review or ('원 대화의 의미를 보존한 저술 초안. 독립 원전 검증이 필요한 세부를 운영 사실로 승격하지 않는다.' if not sources else '구체 실현·관계·한영 의미를 native 검토에서 확인한다.'),
        activation='optional_post_core_only; no genre-wide obligations',qualification='RESEARCH_DRAFT_NOT_NATIVE_APPROVED'))

